#!/usr/bin/env bash
# Starts the Wave 2 developer agents (feat-firmware-base, feat-stt-google, feat-tts-google, feat-llm)
# in sibling worktrees. Run from anywhere: bash ~/Projects/weixue/scripts/orchestrator/start-wave2.sh
set -euo pipefail
cd "$HOME/Projects/weixue"
LAN=$(ipconfig getifaddr en0)

COMMON="Read DESIGN.md, CLAUDE.md, then docs/briefs/<your-task>.md FIRST (verified facts with file:line citations; treat its UNVERIFIED list as things to check yourself). Vendored upstream is read-only at \${WEIXUE_VENDOR:-\$HOME/Projects/weixue-vendor}. Toolchain: source scripts/env.sh. The live backend stack runs from ~/Projects/weixue/server (docker compose, ports 8000/8003, 8004 loopback) — do NOT stop, rebuild or reconfigure it; its secrets are in ~/Projects/weixue/server/.env (never print values). Secrets you may read by path only: Google service account JSON ~/Projects/ha-agent/.secrets/google-cloud-ha.json; ANTHROPIC_API_KEY in ~/Projects/weixue/.env. Deliverables: ONE logical commit on your branch, then .claude/status/dev-complete.json and .claude/status/spec.md per ~/Projects/CLAUDE.md schemas; .claude/status/question.json if blocked on a user-only decision. Comments: final state only, no rationale/history."
SERVER_COMMON="Provider code goes under server/overlay/ mirroring upstream main/xiaozhi-server/ (see docs/server.md 'Adding provider code'). Add pytest tests under server/tests/ with mocked SDK calls plus ONE real smoke test gated by an env var (RUN_LIVE_TESTS=1) that uses the real credential and a short input; run both and record results in spec.md. For an end-to-end check without touching the live stack, you may build the image and run the server with a separate compose project name (-p feat-xxx) ONLY if ports can be remapped via env; otherwise skip live e2e and say so. Also add the provider's config block to server/config/config.template.yaml (do not switch the live selected provider; integration happens at merge). Do not create third-party fork PRs."

declare -A P MODEL
MODEL[firmware-base]=opus; MODEL[stt-google]=sonnet; MODEL[tts-google]=sonnet; MODEL[llm]=sonnet
P[firmware-base]="Task feat-firmware-base (branch feat/firmware-base). $COMMON Build xiaozhi for the 1.75C board per docs/briefs/feat-firmware-base.md: new build entry (name allowed chars only), CONFIG_OTA_URL=http://$LAN:8003/xiaozhi/ota/, language en-US, wake word wn9_jarvis_tts only (ADR-6), device AEC on. Check esptool flash-id for 32MB before switching partition table. Keep OUR changes in this repo under firmware/ (overrides, build script, sdkconfig fragments) with a reproducible script; never edit the vendored clone. The device is on /dev/cu.usbmodem2101 (verify) and a flash backup exists at ~/Projects/weixue/backup/. Erasing and flashing the device is approved by the user. Acceptance: device boots, connects to the OTA URL and WebSocket of the live stack (check docker logs of xiaozhi-esp32-server for the device session, redact tokens), wake word 'Hi Jarvis' triggers listening, one voice round completes (if a mic test needs a human, document exactly what to say and leave it for the user). Record build time and binary sizes in spec.md. If first boot loops on OTA, read the brief's note about server.websocket and wakeup_words in the server config and report instead of editing the live config."
P[stt-google]="Task feat-stt-google (branch feat/stt-google). $COMMON $SERVER_COMMON Implement the Google Cloud Speech-to-Text ASR provider per docs/briefs/feat-stt-google.md: en-US primary with zh-CN as alternative language (multi-language recognition), service-account auth from the JSON path via env/config, LINEAR16 16k, sync recognize is acceptable for v1; structure so streaming can be added later."
P[tts-google]="Task feat-tts-google (branch feat/tts-google). $COMMON $SERVER_COMMON Implement the Google Cloud Text-to-Speech provider per docs/briefs/feat-tts-google.md: Chirp 3 HD voices, language→voice mapping for en-US and cmn-CN (one voice each, configurable), output in the format the server's TTS pipeline expects (see brief), streaming synthesis if the server interface supports chunked audio, else chunk by sentence. Target first-audio latency <1.5 s in the live smoke test; record measured latency."
P[llm]="Task feat-llm (branch feat/llm). $COMMON Read the claude-api skill reference (find it under ~/.claude/skills or ~/.claude/plugins) BEFORE coding, as CLAUDE.md requires. $SERVER_COMMON Implement the Anthropic Claude LLM provider per docs/briefs/feat-llm.md: streaming responses, tool use mapped to the server's function-call/MCP tool mechanism (OpenAI-style tool schemas → input_schema; tool_use/tool_result round trips), default model claude-sonnet-5-5 with claude-haiku-4-5-20251001 configurable, system prompt implementing ADR-7 (English primary, Chinese secondary, reply in the user's language, concise spoken style, home-assistant context). Add the prompt as a file under server/overlay (or config) and document it."

SYS='You are a Developer agent working on a feature in an isolated git worktree. Your job is to implement the feature described in your task, following the project DESIGN.md and CLAUDE.md conventions. When done, write your completion status to .claude/status/dev-complete.json and a feature spec to .claude/status/spec.md. If you hit ambiguity not covered by DESIGN.md, write .claude/status/question.json and exit.'

for b in firmware-base stt-google tts-google llm; do
  wt="../weixue-wt-feat-$b"
  [ -d "$wt" ] || git worktree add -q "$wt" -b "feat/$b" main
  mkdir -p "$wt/.claude/status"
  printf '%s\n' "${P[$b]}" > "$wt/.claude/status/prompt.md"
  ( cd "$wt" && nohup claude -p "$(cat .claude/status/prompt.md)" --dangerously-skip-permissions \
      --model "${MODEL[$b]}" --max-budget-usd 20 --system-prompt "$SYS" \
      > .claude/status/dev-output.log 2>&1 & echo $! > .claude/status/dev.pid )
  echo "feat-$b (${MODEL[$b]}) pid $(cat "$wt/.claude/status/dev.pid")"
done
